/**
 * Admin.tsx — User management + Emergency Controls (admin only). Mobile-responsive.
 */
import { useState, useEffect, useMemo, lazy, Suspense } from "react";
import { useQuery } from "@tanstack/react-query";
import { UserPlus, Link2, Trash2, RefreshCw, KeyRound, AlertTriangle, CheckCircle2, BrainCircuit, HardDrive, Cpu } from "lucide-react";
import { useAuth } from "../contexts/AuthContext";
import { PasswordChecklist, isPasswordValid } from "../components/PasswordChecklist";
import { api } from "../lib/api";
import { RemovedStrategies } from "../components/settings/StrategyRemoval";
import { AdminActivityLog } from "../components/AdminActivityLog";
import { AdminTradeJournal } from "../components/AdminTradeJournal";

import { useSearchParams } from "react-router-dom";
import { LaunchWaitlistAdmin } from "../components/LaunchWaitlist";
const Research = lazy(() => import("./Research").then(m => ({default:m.Research})));

interface User {
  user_id:    string;
  username:   string;
  is_admin:   boolean;
  created_at: string;
}

export function Admin() {
  const { user }      = useAuth();
  const [params, setParams] = useSearchParams();
  const adminTab = params.get("tab") ?? "overview";
  const setAdminTab = (tab: string) => setParams({tab}, {replace:true});
  const [users, setUsers]       = useState<User[]>([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState<string | null>(null);

  const [newUser, setNewUser]   = useState({ username: "", password: "", is_admin: false });
  const [creating, setCreating] = useState(false);
  const [createMsg, setCreateMsg] = useState<{ ok: boolean; msg: string } | null>(null);

  const [resetState, setResetState] = useState<{ uid: string; uname: string; pw: string } | null>(null);
  const [resetMsg,   setResetMsg]   = useState<{ ok: boolean; msg: string } | null>(null);

  const [inviteUrl, setInviteUrl]   = useState<string | null>(null);
  const [inviteProfile, setInviteProfile] = useState("watch");
  const [inviteExp, setInviteExp]   = useState<number>(48);
  const [inviting, setInviting]     = useState(false);
  const [copied, setCopied]         = useState(false);
  const [strategySearch, setStrategySearch] = useState("");
  const { data: ranker, isError: rankerError } = useQuery({
    queryKey: ["admin-learning-ranker-status"],
    queryFn: api.learning.rankerStatus,
    refetchInterval: 60_000,
    retry: false,
  });
  const { data: systemHealth, isError: systemHealthError } = useQuery({
    queryKey: ["admin-system-health"],
    queryFn: api.admin.systemHealth,
    refetchInterval: 60_000,
    retry: false,
  });
  const { data: testedStrategies, isError: testedStrategiesError } = useQuery({
    queryKey: ["admin-tested-strategy-inventory"],
    queryFn: api.settings.testedStrategies,
    staleTime: 5 * 60_000,
    retry: false,
  });
  const strategiesNotRebuilt = useMemo(() => {
    const query = strategySearch.trim().toLowerCase();
    return (testedStrategies?.strategies ?? [])
      .filter(strategy => !strategy.research_supported)
      .filter(strategy => !query || strategy.display_name.toLowerCase().includes(query));
  }, [testedStrategies, strategySearch]);
  const strategiesNotRebuiltCount = (testedStrategies?.strategies ?? []).filter(strategy => !strategy.research_supported).length;

  // ── Emergency / Maintenance state ─────────────────────────────────────────
  const [maintActive,  setMaintActive]  = useState(false);
  const [maintMessage, setMaintMessage] = useState("");
  const [collectionOnly, setCollectionOnly] = useState(false);
  const [maintWorking, setMaintWorking] = useState(false);
  const [maintResult,  setMaintResult]  = useState<{ ok: boolean; msg: string } | null>(null);
  const [showEmergency, setShowEmergency] = useState(false);

  // Load current maintenance status on mount
  useEffect(() => {
    fetch("/api/admin/maintenance/status", { credentials: "include" })
      .then(r => r.ok ? r.json() : null)
      .then(d => { if (d) { setMaintActive(d.active); setMaintMessage(d.message || ""); setCollectionOnly(!!d.collection_only); if (d.active) setShowEmergency(true); } })
      .catch(() => {});
  }, []);

  async function enableMaintenance() {
    const msg = maintMessage.trim();
    const confirmed = window.confirm(
      "⚠️ HALT ALL TRADING\n\n" +
      "This will:\n" +
      (collectionOnly
        ? "  • Keep existing paper loops scanning for research only\n  • Prevent every entry, exit, cancellation, and broker order\n"
        : "  • Immediately stop every bot loop\n") +
      "  • Show the maintenance screen to all users\n" +
      "  • Block the bot from being started\n\n" +
      "Continue?"
    );
    if (!confirmed) return;
    setMaintWorking(true);
    setMaintResult(null);
    try {
      const r = await fetch("/api/admin/maintenance/enable", {
        method: "POST", credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: msg, collection_only: collectionOnly }),
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Failed");
      setMaintActive(true);
      setMaintResult({ ok: true, msg: collectionOnly ? "✅ Trading halted. Paper research collection remains on." : "✅ Maintenance active. All bot loops halted." });
    } catch (e: any) {
      setMaintResult({ ok: false, msg: e.message || "Failed to enable maintenance mode" });
    } finally {
      setMaintWorking(false);
    }
  }

  async function disableMaintenance() {
    setMaintWorking(true);
    setMaintResult(null);
    try {
      const r = await fetch("/api/admin/maintenance/disable", {
        method: "POST", credentials: "include",
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Failed");
      setMaintActive(false);
      setMaintMessage("");
      setMaintResult({ ok: true, msg: "✅ Maintenance cleared. You can now restart the bot." });
    } catch (e: any) {
      setMaintResult({ ok: false, msg: e.message || "Failed to clear maintenance mode" });
    } finally {
      setMaintWorking(false);
    }
  }

  async function loadUsers() {
    setLoading(true);
    setError(null);
    try {
      const r = await fetch("/api/admin/users", { credentials: "include" });
      if (!r.ok) throw new Error("Unauthorized or server error");
      const d = await r.json();
      setUsers(d.users || []);
    } catch (e: any) {
      setError(e.message || "Failed to load users");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { loadUsers(); }, []);

  async function createUser() {
    if (!newUser.username || !newUser.password) {
      setCreateMsg({ ok: false, msg: "Username and password required" });
      return;
    }
    if (!isPasswordValid(newUser.password)) {
      setCreateMsg({ ok: false, msg: "Password does not meet complexity requirements." });
      return;
    }
    setCreating(true);
    setCreateMsg(null);
    try {
      const r = await fetch("/api/admin/users", {
        method: "POST", credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newUser),
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Create failed");
      setCreateMsg({ ok: true, msg: `User "${newUser.username}" created.` });
      setNewUser({ username: "", password: "", is_admin: false });
      loadUsers();
    } catch (e: any) {
      setCreateMsg({ ok: false, msg: e.message || "Create failed" });
    } finally {
      setCreating(false);
    }
  }

  async function deleteUser(uid: string, uname: string) {
    if (!confirm(`Delete user "${uname}"? This cannot be undone.`)) return;
    try {
      const r = await fetch(`/api/admin/users/${uid}`, {
        method: "DELETE", credentials: "include"
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Delete failed");
      loadUsers();
    } catch (e: any) {
      alert(e.message || "Delete failed");
    }
  }

  async function resetPassword() {
    if (!resetState || !isPasswordValid(resetState.pw)) {
      setResetMsg({ ok: false, msg: "Password does not meet complexity requirements." });
      return;
    }
    try {
      const r = await fetch(`/api/admin/users/${resetState.uid}/reset-password`, {
        method: "POST", credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ new_password: resetState.pw }),
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Reset failed");
      setResetMsg({ ok: true, msg: "Password updated!" });
      setTimeout(() => { setResetState(null); setResetMsg(null); }, 1500);
    } catch (e: any) {
      setResetMsg({ ok: false, msg: e.message || "Reset failed" });
    }
  }

  async function generateInvite() {
    setInviting(true);
    setInviteUrl(null);
    try {
      const r = await fetch("/api/admin/invite", {
        method: "POST", credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ hours: inviteExp, access_profile: inviteProfile }),
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.detail || "Failed");
      setInviteUrl(d.link);
    } catch (e: any) {
      alert(e.message || "Failed to generate invite");
    } finally {
      setInviting(false);
    }
  }

  function copyInvite() {
    if (!inviteUrl) return;
    navigator.clipboard.writeText(inviteUrl).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  return (
    <div className="p-4 flex flex-col gap-4" style={{ maxWidth: 1600, width: "100%" }}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div><h2 className="text-lg font-semibold" style={{ color: "var(--ink)" }}>Admin</h2><p className="text-xs mt-1" style={{ color: "var(--ink-muted)" }}>System status and account access</p></div>
        <button className="btn btn-ghost" onClick={loadUsers}>
          <RefreshCw size={13} />
        </button>
      </div>

      <div role="tablist" aria-label="Admin sections" className="flex gap-2">
        <button id="admin-overview-tab" role="tab" aria-selected={adminTab === "overview"}
          aria-controls="admin-overview-panel" className={`btn ${adminTab === "overview" ? "btn-primary" : "btn-ghost"}`}
          onClick={() => setAdminTab("overview")}>Overview</button>
        <button id="admin-journal-tab" role="tab" aria-selected={adminTab === "journal"}
          aria-controls="admin-journal-panel" className={`btn ${adminTab === "journal" ? "btn-primary" : "btn-ghost"}`}
          onClick={() => setAdminTab("journal")}>Trade journal</button>
      </div>
      <div className="flex gap-2"><button className={`btn ${adminTab === "research" ? "btn-primary" : "btn-ghost"}`} onClick={() => setAdminTab("research")}>Research</button><button className={`btn ${adminTab === "launch" ? "btn-primary" : "btn-ghost"}`} onClick={() => setAdminTab("launch")}>Launch waitlist</button></div>
      {adminTab === "research" && user?.is_admin && <Suspense fallback={<p>Loading research...</p>}><Research /></Suspense>}
      {adminTab === "launch" && user?.is_admin && <LaunchWaitlistAdmin />}
      {adminTab === "journal" && user?.is_admin && <div id="admin-journal-panel" role="tabpanel" aria-labelledby="admin-journal-tab"><AdminTradeJournal /></div>}
      <div id="admin-overview-panel" role="tabpanel" aria-labelledby="admin-overview-tab" hidden={adminTab !== "overview"}>
      <div className="flex flex-col gap-4" style={{ maxWidth: 600 }}>
      {user?.is_admin && <AdminActivityLog />}
      <RemovedStrategies />
      <section className="card px-3 py-2" aria-label="Machine learning readiness">
        {rankerError ? <p className="text-xs" style={{ color: "var(--negative)" }}>ML readiness unavailable</p> : ranker ? (() => {
          const required = ranker.required ?? 1000;
          const usable = ranker.usable_episodes;
          const remaining = ranker.remaining ?? Math.max(0, required - usable);
          const pct = required > 0 ? Math.min(100, usable / required * 100) : 0;
          return <>
            <div className="flex items-center gap-2 flex-wrap text-xs">
              <BrainCircuit size={15} style={{ color: "var(--accent)" }} />
              <strong style={{ color: "var(--ink)" }}>ML Ranker</strong>
              <span className="badge badge-yellow">COLLECTING</span>
              <span style={{ color: "var(--ink-muted)" }}><strong style={{ color: "var(--ink)" }}>{usable}/{required.toLocaleString()}</strong> usable episodes</span>
              <span className="ml-auto" style={{ color: "var(--ink-faint)" }}>No trading authority</span>
            </div>
            <div className="mt-2 h-1 rounded-full overflow-hidden" style={{ background: "var(--surface-raised)" }} role="progressbar" aria-valuenow={usable} aria-valuemin={0} aria-valuemax={required} aria-label="Usable ML episodes">
              <div className="h-full rounded-full" style={{ width: `${pct}%`, minWidth: usable > 0 ? 4 : 0, background: "var(--accent)" }} />
            </div>
            <details className="mt-1"><summary className="text-[10px] cursor-pointer" style={{ color: "var(--ink-faint)" }}>{remaining.toLocaleString()} still needed · What counts?</summary><p className="text-xs mt-2" style={{ color: "var(--ink-muted)" }}>Only complete, independent setup outcomes count—not total trades or repeated scanner checks. The model remains off and cannot approve, reject, size, or place trades.</p></details>
          </>;
        })() : <p className="text-xs" style={{ color: "var(--ink-muted)" }}>Loading ML readiness…</p>}
      </section>

      <section className="card p-3" aria-label="Server health">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div className="rounded-lg px-3 py-2" style={{ background: "var(--muted)" }}>
            <div className="flex items-center gap-2 text-xs">
              <HardDrive size={15} style={{ color: systemHealth?.disk.status === "critical" ? "var(--negative)" : systemHealth?.disk.status === "watch" ? "var(--warning)" : "var(--positive)" }} />
              <strong style={{ color: "var(--ink)" }}>Server storage</strong>
              {systemHealthError ? <span style={{ color: "var(--negative)" }}>unavailable</span> : systemHealth ? <span className="ml-auto" style={{ color: systemHealth.disk.status === "good" ? "var(--positive)" : systemHealth.disk.status === "watch" ? "var(--warning)" : "var(--negative)" }}>
                {systemHealth.disk.status === "good" ? "Good" : systemHealth.disk.status === "watch" ? "Getting full" : "Action needed"}
              </span> : <span style={{ color: "var(--ink-muted)" }}>checking…</span>}
            </div>
            {systemHealth && <p className="text-[10px] mt-1" style={{ color: "var(--ink-muted)" }}>
              {systemHealth.disk.used_percent}% used · {(systemHealth.disk.free_bytes / 1024 ** 3).toFixed(1)} GB free
            </p>}
          </div>
          <div className="rounded-lg px-3 py-2" style={{ background: "var(--muted)" }}>
            <div className="flex items-center gap-2 text-xs">
              <Cpu size={15} style={{ color: systemHealth?.cpu.status === "critical" ? "var(--negative)" : systemHealth?.cpu.status === "watch" ? "var(--warning)" : "var(--positive)" }} />
              <strong style={{ color: "var(--ink)" }}>Server CPU</strong>
              {systemHealthError ? <span style={{ color: "var(--negative)" }}>unavailable</span> : systemHealth ? <span className="ml-auto" style={{ color: systemHealth.cpu.status === "good" ? "var(--positive)" : systemHealth.cpu.status === "watch" ? "var(--warning)" : "var(--negative)" }}>
                {systemHealth.cpu.status === "good" ? "Good" : systemHealth.cpu.status === "watch" ? "Working hard" : "Action needed"}
              </span> : <span style={{ color: "var(--ink-muted)" }}>checking…</span>}
            </div>
            {systemHealth && <p className="text-[10px] mt-1" style={{ color: "var(--ink-muted)" }}>
              {systemHealth.cpu.used_percent}% busy · {systemHealth.cpu.cores} CPU core{systemHealth.cpu.cores === 1 ? "" : "s"}
            </p>}
          </div>
        </div>
      </section>

      <details className="card p-4">
        <summary className="text-sm font-semibold cursor-pointer" style={{ color: "var(--ink)" }}>
          Strategies not rebuilt ({strategiesNotRebuiltCount})
        </summary>
        <div className="mt-3">
          <p className="text-xs" style={{ color: "var(--ink-muted)" }}>Saved test ideas that do not yet have a runnable all-ticker rule. They are not running and cannot trade.</p>
          <input className="input w-full mt-3" value={strategySearch} onChange={event => setStrategySearch(event.target.value)} placeholder="Find a strategy" aria-label="Find a strategy that is not rebuilt" />
          {testedStrategiesError ? <p className="text-xs mt-3" style={{ color: "var(--negative)" }}>Strategy list unavailable.</p> : !testedStrategies ? <p className="text-xs mt-3" style={{ color: "var(--ink-muted)" }}>Loading strategy list…</p> : strategiesNotRebuilt.length ? <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-1 mt-3 max-h-64 overflow-y-auto">
            {strategiesNotRebuilt.map(strategy => <p key={strategy.strategy_id} className="text-xs py-1 border-b" style={{ color: "var(--ink)", borderColor: "var(--border)" }}>{strategy.display_name}</p>)}
          </div> : <p className="text-xs mt-3" style={{ color: "var(--ink-muted)" }}>{strategySearch ? "No strategies match that search." : "Every saved strategy has been rebuilt."}</p>}
        </div>
      </details>

      {/* ── Emergency Controls ──────────────────────────────────────────── */}
      <div
        className="card p-4 flex flex-col gap-3"
        style={{
          borderColor: maintActive ? "rgba(251,113,133,0.4)" : "rgba(255,255,255,0.06)",
          background:  maintActive ? "rgba(239,68,68,0.06)" : undefined,
        }}
      >
        {/* Section header + status badge */}
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <h3 className="text-sm font-semibold flex items-center gap-2" style={{ color: "var(--ink)" }}>
            <AlertTriangle size={15} color={maintActive ? "#f87171" : "var(--ink-muted)"} />
            Emergency Controls
          </h3>
          <span
            className="text-xs font-semibold px-2 py-0.5 rounded-full"
            style={{
              background: maintActive ? "rgba(239,68,68,0.15)" : "rgba(0,200,83,0.12)",
              color:      maintActive ? "#f87171" : "#00c853",
              border:     `1px solid ${maintActive ? "rgba(239,68,68,0.3)" : "rgba(0,200,83,0.25)"}`,
            }}
          >
            {maintActive ? "🔴 MAINTENANCE ACTIVE" : "✅ BOT OPERATIONAL"}
          </span>
        </div>

        {!maintActive && <button className="btn btn-ghost text-xs" onClick={() => setShowEmergency(value => !value)}>
          {showEmergency ? "Hide controls" : "Manage maintenance"}
        </button>}

        {(showEmergency || maintActive) && <>
        <p className="text-xs leading-relaxed" style={{ color: "var(--ink-muted)" }}>
          {maintActive
            ? (collectionOnly
              ? "Trading is halted for every user. Existing paper loops may only scan and record research data; no entries, exits, cancellations, or broker orders can be sent."
              : "Every bot loop is halted and all users see the maintenance screen. Type a new message below and save, or clear maintenance when ready.")
            : "Use when trading must stop for everyone. You can optionally keep existing paper loops collecting research data without allowing any orders."}
        </p>

        {/* Message / ETA input */}
        <div className="flex flex-col gap-1">
          <label className="text-xs font-medium" style={{ color: "var(--ink-muted)" }}>
            Message shown to users (e.g. "Back online by 3 PM ET" or "Estimated downtime: 1–2 hours")
          </label>
          <textarea
            className="input"
            rows={2}
            style={{ fontSize: 13, resize: "vertical" }}
            placeholder="Describe the issue or give an estimated return time…"
            value={maintMessage}
            onChange={e => setMaintMessage(e.target.value)}
          />
        </div>

        {!maintActive && (
          <label className="flex items-start gap-2 text-xs" style={{ color: "var(--ink-muted)" }}>
            <input
              type="checkbox"
              checked={collectionOnly}
              onChange={e => setCollectionOnly(e.target.checked)}
              style={{ marginTop: 2 }}
            />
            <span>
              <strong style={{ color: "var(--ink)" }}>Keep paper research collection running</strong><br />
              Existing loops can scan and record signals/quotes. Every entry, exit, order cancellation, and broker order remains blocked.
            </span>
          </label>
        )}

        {/* Action buttons */}
        <div className="flex gap-2 flex-wrap">
          {!maintActive ? (
            <button
              className="btn flex items-center gap-2"
              style={{
                background: "#dc2626", color: "#fff", border: "none",
                fontWeight: 700, flex: 1, minWidth: 200,
              }}
              onClick={enableMaintenance}
              disabled={maintWorking}
            >
              <AlertTriangle size={14} />
              {maintWorking ? "Halting all bots…" : "🔴 Halt All Trading for Maintenance"}
            </button>
          ) : (
            <>
              {/* Update message without disabling */}
              <button
                className="btn btn-ghost flex items-center gap-2"
                style={{ flex: 1, minWidth: 140 }}
                onClick={async () => {
                  setMaintWorking(true);
                  try {
                    // Re-enable with new message to update it
                    const r = await fetch("/api/admin/maintenance/enable", {
                      method: "POST", credentials: "include",
                      headers: { "Content-Type": "application/json" },
                      body: JSON.stringify({ message: maintMessage.trim(), collection_only: collectionOnly }),
                    });
                    if (r.ok) setMaintResult({ ok: true, msg: "Message updated." });
                  } catch { /* ignore */ } finally { setMaintWorking(false); }
                }}
                disabled={maintWorking}
              >
                Save Message
              </button>
              <button
                className="btn flex items-center gap-2"
                style={{
                  background: "#00c853", color: "#000", border: "none",
                  fontWeight: 700, flex: 1, minWidth: 140,
                }}
                onClick={disableMaintenance}
                disabled={maintWorking}
              >
                <CheckCircle2 size={14} />
                {maintWorking ? "Clearing…" : "✅ Clear — Bring Bot Back Online"}
              </button>
            </>
          )}
        </div>

        {maintResult && (
          <p className="text-xs" style={{ color: maintResult.ok ? "#00c853" : "#f87171" }}>
            {maintResult.msg}
          </p>
        )}
        </>}
      </div>

      {/* Users list — card-per-user on mobile, table on larger screens */}
      <div className="card p-4">
        <h3 className="text-sm font-semibold mb-3" style={{ color: "var(--ink)" }}>
          All Users
        </h3>
        {error && (
          <p className="text-xs mb-2" style={{ color: "#f87171" }}>{error}</p>
        )}
        {loading ? (
          <p className="text-xs" style={{ color: "var(--ink-muted)" }}>Loading…</p>
        ) : (
          <div className="flex flex-col gap-2">
            {users.map(u => (
              <div key={u.user_id}
                style={{
                  border: "1px solid rgba(255,255,255,0.06)",
                  borderRadius: 8,
                  padding: "10px 12px",
                  background: resetState?.uid === u.user_id ? "rgba(0,200,83,0.03)" : undefined,
                }}
              >
                {/* User row */}
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                  {/* Name + role */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ fontSize: 14, color: "var(--ink)", fontWeight: 500 }}>
                      {u.username}
                    </span>
                    {u.user_id === user?.user_id && (
                      <span style={{ fontSize: 10, color: "var(--accent)", marginLeft: 6 }}>you</span>
                    )}
                    <span style={{
                      fontSize: 11, marginLeft: 8,
                      color: u.is_admin ? "var(--accent)" : "var(--ink-muted)",
                    }}>
                      {u.is_admin ? "Admin" : "Member"}
                    </span>
                    <span style={{ fontSize: 11, color: "var(--ink-faint)", marginLeft: 8 }}>
                      {u.created_at ? new Date(u.created_at).toLocaleDateString() : ""}
                    </span>
                  </div>
                  {/* Actions */}
                  <div style={{ display: "flex", gap: 4, flexShrink: 0 }}>
                    <button
                      className="btn btn-ghost"
                      style={{ padding: "4px 10px", fontSize: 12 }}
                      title="Reset password"
                      onClick={() => {
                        setResetMsg(null);
                        setResetState(resetState?.uid === u.user_id
                          ? null
                          : { uid: u.user_id, uname: u.username, pw: "" });
                      }}
                    >
                      <KeyRound size={13} />
                    </button>
                    {u.user_id !== user?.user_id && (
                      <button
                        className="btn btn-ghost"
                        style={{ padding: "4px 10px", fontSize: 12, color: "var(--negative)" }}
                        title="Delete user"
                        onClick={() => deleteUser(u.user_id, u.username)}
                      >
                        <Trash2 size={13} />
                      </button>
                    )}
                  </div>
                </div>

                {/* Inline reset password — shown below user row on all screen sizes */}
                {resetState?.uid === u.user_id && (
                  <div style={{ marginTop: 10, display: "flex", flexDirection: "column", gap: 8 }}>
                    <span style={{ fontSize: 12, color: "var(--ink-muted)" }}>
                      New password for <strong style={{ color: "var(--ink)" }}>{u.username}</strong>:
                    </span>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                      <input
                        type="password"
                        className="input"
                        style={{ fontSize: 12, padding: "4px 10px", flex: 1, minWidth: 160 }}
                        placeholder="12+ chars, upper, lower, number, special"
                        value={resetState.pw}
                        autoFocus
                        onChange={e => setResetState(s => s ? { ...s, pw: e.target.value } : null)}
                        onKeyDown={e => e.key === "Enter" && resetPassword()}
                      />
                      <button className="btn btn-primary" style={{ fontSize: 12, padding: "4px 12px" }} onClick={resetPassword}>
                        Set
                      </button>
                      <button className="btn btn-ghost" style={{ fontSize: 12, padding: "4px 10px" }}
                        onClick={() => { setResetState(null); setResetMsg(null); }}>
                        Cancel
                      </button>
                    </div>
                    <PasswordChecklist password={resetState.pw} style={{ paddingLeft: 2 }} />
                    {resetMsg && (
                      <span style={{ fontSize: 12, color: resetMsg.ok ? "var(--accent)" : "#f87171" }}>
                        {resetMsg.msg}
                      </span>
                    )}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Infrequent account actions stay collapsed until needed. */}
      <details className="card p-4">
        <summary className="text-sm font-semibold cursor-pointer" style={{ color: "var(--ink)" }}>Add a user</summary>
        <div className="flex flex-col gap-3 mt-3">
          {/* Stack inputs vertically on mobile */}
          <div className="flex flex-col gap-2 sm:flex-row">
            <input
              className="input flex-1"
              placeholder="Username"
              value={newUser.username}
              onChange={e => setNewUser(n => ({ ...n, username: e.target.value }))}
            />
            <input
              className="input flex-1"
              type="password"
              placeholder="12+ chars, upper, lower, number, special"
              value={newUser.password}
              onChange={e => setNewUser(n => ({ ...n, password: e.target.value }))}
            />
          </div>
          <PasswordChecklist password={newUser.password} style={{ paddingLeft: 2 }} />
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={newUser.is_admin}
              onChange={e => setNewUser(n => ({ ...n, is_admin: e.target.checked }))}
            />
            <span className="text-sm" style={{ color: "var(--ink)" }}>Grant admin access</span>
          </label>
          {createMsg && (
            <p className="text-xs" style={{ color: createMsg.ok ? "var(--accent)" : "#f87171" }}>
              {createMsg.msg}
            </p>
          )}
          <button className="btn btn-primary" onClick={createUser} disabled={creating}>
            <UserPlus size={14} />
            {creating ? "Creating…" : "Create User"}
          </button>
        </div>
      </details>

      {/* Invite link */}
      <details className="card p-4">
        <summary className="text-sm font-semibold cursor-pointer" style={{ color: "var(--ink)" }}>Create an invite link</summary>
        <div className="mt-3">
        <p className="text-xs mb-3" style={{ color: "var(--ink-muted)" }}>
          Create a customer preview account. Watch-only provides charts. Learning adds guided chart practice. Neither can connect a broker or place orders. Existing accounts stay unchanged.
        </p>
        <div className="flex items-center gap-2 mb-3 flex-wrap">
          <label className="text-sm">Access <select className="select" value={inviteProfile} onChange={e => setInviteProfile(e.target.value)}><option value="watch">Watch-only preview</option><option value="learning">Learning preview</option></select></label>
          <label className="text-sm" style={{ color: "var(--ink)" }}>Expires in</label>
          <select
            className="select"
            value={inviteExp}
            onChange={e => setInviteExp(Number(e.target.value))}
          >
            <option value={24}>24 hours</option>
            <option value={48}>48 hours</option>
            <option value={72}>72 hours</option>
            <option value={168}>7 days</option>
          </select>
        </div>
        <button className="btn btn-primary mb-3" onClick={generateInvite} disabled={inviting} style={{ width: "100%" }}>
          <Link2 size={14} />
          {inviting ? "Generating…" : "Generate Invite Link"}
        </button>
        {inviteUrl && (
          <div className="flex flex-col gap-2">
            <div
              className="input text-xs font-mono"
              style={{ wordBreak: "break-all", userSelect: "all",
                background: "rgba(0,200,83,0.06)", borderColor: "rgba(0,200,83,0.2)" }}
            >
              {inviteUrl}
            </div>
            <button className="btn btn-ghost" onClick={copyInvite} style={{ width: "100%" }}>
              {copied ? "Copied!" : "Copy Link"}
            </button>
          </div>
        )}
        </div>
      </details>
      </div>
      </div>
    </div>
  );
}
